import java.util.function.*;
import java.util.List;

public class Lambdas {
    public static void main(String[] args) {
        Predicate<Integer> isEven = n -> n % 2 == 0;
        Function<Integer, Integer> square = n -> n * n;
        Consumer<String> print = s -> System.out.println("Got: " + s);
        Supplier<String> greeting = () -> "Hello!";

        System.out.println(isEven.test(4) + " " + square.apply(5));
        print.accept(greeting.get());

        int factor = 10;                       // effectively final
        Function<Integer, Integer> scale = n -> n * factor;
        System.out.println(scale.apply(3));    // 30
    }
}
